      "requirement": {
        "title": "Rate limit account creation",
        "given": "sign-up requests arrive from the same source",
        "when": "request rate exceeds reasonable thresholds",
        "then": "block or throttle further sign-ups, require CAPTCHA after threshold, and alert fraud monitoring"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Fake accounts created with unverified emails receive credits",
      "scenario": "Since sign-up requires only an email address with no verification, an attacker registers accounts using email addresses they don't own (victim@company.com). These fake accounts accumulate credits, the actual email owner may receive unwanted emails, and the system cannot distinguish real users from spoofed identities. This violates anti-spam laws and damages trust.",
