      "requirement": {
        "title": "Verify email ownership before account activation",
        "given": "a new account is created",
        "when": "email address is provided",
        "then": "send verification link and prevent account activation or credit allocation until email is confirmed"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Referral code sharing allows coordinated abuse at scale",
      "scenario": "Users share one popular referral code across social media or forums. Without limits on how many times a code can be used, thousands of people could sign up with the same code, each giving the original user $10. Combined with no email verification or rate limiting, this allows viral abuse where one person could gain thousands of dollars in credits through social engineering.",
