        "title": "Limit referral code usage per period",
        "given": "a referral code is used",
        "when": "usage count is checked",
        "then": "enforce maximum number of successful referrals per code per day/month and flag suspicious patterns for manual review"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Attacker spams victim's inbox by signing up with their email repeatedly",
      "scenario": "An attacker enters a victim's email address during sign-up multiple times with different referral codes. Since there's no email verification or rate limiting per email mentioned, the victim receives dozens of sign-up emails. This constitutes email bombing, damages the platform's reputation, and could cause legal liability under anti-spam laws.",
      "component": "Sign-up API and email notification system",
      "likelihood": 4,
      "impact": 3,
