      "cwe": ["CWE-362"],
      "plainLanguage": "If two people sign up with the same referral code at exactly the same time, the system might pay out twice",
      "requirement": {
        "title": "Use atomic transactions for credit allocation",
        "given": "credit allocation is triggered",
        "when": "concurrent sign-ups occur",
        "then": "use database transactions with proper locking to ensure credits are allocated exactly once per referral event"
      }
    },
    {
      "stride": "Repudiation",
      "title": "No audit trail to prove who created fraudulent referral accounts",
      "scenario": "When fraudulent referral activity is detected (mass fake sign-ups), the system lacks audit logs showing IP addresses, device fingerprints, or timestamps. This makes it impossible to attribute the abuse to specific actors, investigate patterns, or provide evidence for legal action. Legitimate users could also deny responsibility for suspicious referrals from their codes.",
      "component": "Sign-up API and audit logging",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        {
          "quote": "Sign-up only needs an email address."
        }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "The system can't prove who created fake accounts or used referral codes improperly",
      "requirement": {
        "title": "Log all referral and sign-up activity",
        "given": "a sign-up or referral credit event occurs",
        "when": "the action is processed",
        "then": "log timestamp, IP address, user agent, email, referral code used, credit amount, and any anomaly flags in a tamper-evident audit trail"
      }
    }
  ]
}
